class Solution {
public:
    int numberOfWays(int startPos, int endPos, int k) {
        const long long MOD = 1000000007;
        int d = endPos > startPos ? endPos - startPos : startPos - endPos;

        if (d > k || (k + d) % 2 != 0) return 0;

        int r = (k + d) / 2;

        long long num = 1, den = 1;
        for (int i = 0; i < r; i++) {
            num = num * (k - i) % MOD;
            den = den * (i + 1) % MOD;
        }

        return (int)(num * modPow(den, MOD - 2, MOD) % MOD);
    }

private:
    long long modPow(long long base, long long exp, long long mod) {
        long long result = 1;
        base %= mod;
        while (exp > 0) {
            if (exp & 1) result = result * base % mod;
            base = base * base % mod;
            exp >>= 1;
        }
        return result;
    }
};
